#!/usr/bin/env python3
"""Original texture set "Pastel Meadow": soft, banded, cartoon-pixel blocks. CC0, generated by code (seeded, repeatable).

  python examples/texture-pack-demo/make_textures.py out/pack-src --res 16        # 16x16 (also 32 and 64)

Output mirrors assets/minecraft/textures/ (block/*.png, item/*.png, animated strips + .png.mcmeta).
Design rules that keep the set coherent:
  * ONE global palette plan: every material is a 4-tone ramp (dark -> light) with a slight hue shift
  * tileable by construction: all noise and cell patterns wrap around the tile edges
  * flat bands instead of smooth gradients; a few single-pixel accents per texture (never many)
"""
import argparse
import json
import math
import random
import sys
from pathlib import Path

from PIL import Image

sys.path.insert(0, str(Path(__file__).resolve().parents[2] / "core"))
from skin import ramp  # noqa: E402  (same ramp helper the skin tools use)

PLAN = {  # material -> base colour; each becomes a 4-tone ramp
    "stone": "8890a8", "earth": "8a6446", "grass": "6bb350", "wood": "b98550", "bark": "7a5538", "leaf": "56a85a",
    "sand": "ead9a4", "brick": "c56a5a", "obsidian": "3b2f5c", "glow": "f6d775", "snow": "eef4fa", "wool": "f3eee6",
    "gold": "f7cf4a", "diamond": "68d8d6", "tnt": "d9534f", "paper": "efe2c0", "water": "4a8fe0", "lava": "ee7a25",
    "metal": "b9bec9",
}
R = {k: ramp(v, 4, spread=0.2, hue_shift=0.05) for k, v in PLAN.items()}


class Gen:
    def __init__(self, n, seed=5):
        self.n, self.rng = n, random.Random(seed)

    # ---- tileable noise: a coarse lattice with wrap-around bilinear interpolation, plus fine per-pixel noise
    def noise(self, cells=4, fine=0.22):
        n, rng = self.n, self.rng
        cells = max(2, cells * n // 16)
        lat = [[rng.random() for _ in range(cells)] for _ in range(cells)]
        out = [[0.0] * n for _ in range(n)]
        for y in range(n):
            for x in range(n):
                gx, gy = x * cells / n, y * cells / n
                x0, y0 = int(gx) % cells, int(gy) % cells; x1, y1 = (x0 + 1) % cells, (y0 + 1) % cells
                fx, fy = gx - int(gx), gy - int(gy)
                fx, fy = fx * fx * (3 - 2 * fx), fy * fy * (3 - 2 * fy)
                a = lat[y0][x0] * (1 - fx) + lat[y0][x1] * fx; b = lat[y1][x0] * (1 - fx) + lat[y1][x1] * fx
                out[y][x] = (a * (1 - fy) + b * fy) * (1 - fine) + rng.random() * fine
        return out

    def banded(self, tones, cells=4, fine=0.22, bias=0.0):
        """Image whose pixels pick a tone of the ramp by tileable noise."""
        v = self.noise(cells, fine); n = self.n
        im = Image.new("RGBA", (n, n))
        for y in range(n):
            for x in range(n):
                t = min(len(tones) - 1, max(0, int((v[y][x] + bias) * len(tones))))
                im.putpixel((x, y), tones[t])
        return im

    def cells(self, tones, count=7, border=True):
        """Voronoi cells that wrap (cobblestone, bricks-like stone)."""
        n, rng = self.n, self.rng
        pts = [(rng.random() * n, rng.random() * n) for _ in range(count * n // 16 + 1)]
        tone = [rng.randrange(1, len(tones)) for _ in pts]
        im = Image.new("RGBA", (n, n))
        for y in range(n):
            for x in range(n):
                ds = sorted((min(((x - px + ox) ** 2 + (y - py + oy) ** 2) for ox in (-n, 0, n) for oy in (-n, 0, n)), i) for i, (px, py) in enumerate(pts))
                (d1, i1), (d2, _) = ds[0], ds[1]
                im.putpixel((x, y), tones[0] if border and (math.sqrt(d2) - math.sqrt(d1)) < max(0.7, n / 26) else tones[tone[i1]])
        return im

    def accents(self, im, color, k):
        for _ in range(k * self.n // 16):
            im.putpixel((self.rng.randrange(self.n), self.rng.randrange(self.n)), color)
        return im


def make_all(n, seed=5):
    g = Gen(n, seed)
    out = {}
    s = n / 16
    out["block/stone"] = g.accents(g.banded(R["stone"], 4, 0.25), R["stone"][3], 6)
    out["block/cobblestone"] = g.cells(R["stone"], 13)
    out["block/dirt"] = g.accents(g.banded(R["earth"], 4, 0.30), R["earth"][0], 8)
    out["block/grass_block_top"] = g.accents(g.banded(R["grass"], 4, 0.28), R["grass"][3], 8)
    # grass side: dirt with a ragged fringe of grass on top
    side = g.banded(R["earth"], 4, 0.30)
    fringe = [max(2, int(n * 0.2) + g.rng.randrange(-1, 2) * max(1, int(s))) for _ in range(n)]
    top = g.banded(R["grass"], 4, 0.28)
    for x in range(n):
        for y in range(fringe[x]):
            side.putpixel((x, y), top.getpixel((x, y)))
    out["block/grass_block_side"] = side
    # planks: boards of height n/4 with staggered joints and a dark seam
    planks = Image.new("RGBA", (n, n)); grain = g.noise(8, 0.25); rows = 4; bh = n // rows
    for r in range(rows):
        joint = g.rng.randrange(n)
        for y in range(bh):
            for x in range(n):
                yy = r * bh + y
                tone = R["wood"][1 + (grain[yy][x] > 0.55) + (grain[yy][x] > 0.85)] if y not in (bh - 1,) else R["wood"][0]
                if x == joint:
                    tone = R["wood"][0]
                planks.putpixel((x, yy), tone)
    out["block/oak_planks"] = planks
    log = Image.new("RGBA", (n, n)); lg = g.noise(8, 0.2)
    for y in range(n):
        for x in range(n):
            col = (x * 8 // n) % 2
            log.putpixel((x, y), R["bark"][min(3, (1 if col else 0) + (lg[y][x] > 0.6) * 1 + (lg[y][x] > 0.9))])
    out["block/oak_log"] = log
    top = Image.new("RGBA", (n, n))
    for y in range(n):
        for x in range(n):
            d = max(abs(x - (n - 1) / 2), abs(y - (n - 1) / 2)) * 2 / n * 8
            top.putpixel((x, y), R["wood"][[3, 2, 3, 2, 3, 1, 1, 0, 0][min(8, int(d))]] if d < 6 else R["bark"][1])
    out["block/oak_log_top"] = top
    leaves = g.banded(R["leaf"], 5, 0.4)
    for _ in range(n * n // 7):  # holes so the canopy reads as leaves, not a green cube
        leaves.putpixel((g.rng.randrange(n), g.rng.randrange(n)), (0, 0, 0, 0))
    out["block/oak_leaves"] = leaves
    out["block/sand"] = g.accents(g.banded(R["sand"], 4, 0.25), R["sand"][0], 6)
    out["block/snow_block"] = g.banded(R["snow"], 3, 0.15)
    out["block/white_wool"] = g.banded(R["wool"], 8, 0.12, bias=0.12)
    out["block/obsidian"] = g.accents(g.banded(R["obsidian"], 4, 0.3), R["obsidian"][3], 5)
    out["block/glowstone"] = g.accents(g.cells(R["glow"], 8, border=False), R["glow"][3], 6)
    # bricks
    br = Image.new("RGBA", (n, n)); bh = n // 4
    for r in range(4):
        off = (bh if r % 2 else 0)
        for y in range(bh):
            for x in range(n):
                mortar = y == bh - 1 or (x + off) % (n // 2) == 0
                br.putpixel((x, r * bh + y), R["paper"][1] if mortar else R["brick"][1 + (g.rng.random() > 0.7) + (g.rng.random() > 0.95)])
    out["block/bricks"] = br
    for name, key in (("gold_block", "gold"), ("diamond_block", "diamond")):
        im = g.banded(R[key], 3, 0.2)
        for i in range(n):  # bevel: light top-left, dark bottom-right
            im.putpixel((i, 0), R[key][3]); im.putpixel((0, i), R[key][3]); im.putpixel((i, n - 1), R[key][0]); im.putpixel((n - 1, i), R[key][0])
        out[f"block/{name}"] = im
    # TNT
    for part in ("side", "top", "bottom"):
        im = g.banded(R["tnt"], 3, 0.15)
        if part == "side":
            for y in range(n * 5 // 16, n * 11 // 16):
                for x in range(n):
                    im.putpixel((x, y), R["paper"][2] if y not in (n * 5 // 16, n * 11 // 16 - 1) else R["paper"][0])
        else:
            for i in range(n):
                im.putpixel((i, n // 2), R["tnt"][0]); im.putpixel((n // 2, i), R["tnt"][0])
        out[f"block/tnt_{part}"] = im
    # glass: transparent with a frame and a glint
    gl = Image.new("RGBA", (n, n), (*R["diamond"][3][:3], 40))
    for i in range(n):
        for p in ((i, 0), (i, n - 1), (0, i), (n - 1, i)):
            gl.putpixel(p, (*R["metal"][3][:3], 255))
    for i in range(2, max(4, n // 3)):
        gl.putpixel((i, n - 1 - i), (255, 255, 255, 190))
    out["block/glass"] = gl
    # animated water / lava: a tileable base scrolled one row-step per frame (loops seamlessly)
    for name, key, alpha, frametime in (("water_still", "water", 190, 3), ("lava_still", "lava", 255, 4)):
        frames = 8; base = g.banded(R[key], 4, 0.3)
        strip = Image.new("RGBA", (n, n * frames))
        for f in range(frames):
            for y in range(n):
                for x in range(n):
                    c = base.getpixel((x, (y + f * n // frames) % n))
                    strip.putpixel((x, f * n + y), (c[0], c[1], c[2], alpha))
        out[f"block/{name}"] = (strip, {"animation": {"frametime": frametime, "interpolate": key == "water"}})
    # items (not tiles): a gem and a stick
    gem = Image.new("RGBA", (n, n), (0, 0, 0, 0)); c = (n - 1) / 2
    for y in range(n):
        for x in range(n):
            d = abs(x - c) / (n * 0.38) + abs(y - c) / (n * 0.44)
            if d < 1:
                gem.putpixel((x, y), R["diamond"][3 if (x + y) < n * 0.9 and d < 0.55 else 2 if d < 0.8 else 1])
            elif d < 1.2:
                gem.putpixel((x, y), R["diamond"][0])
    out["item/diamond"] = gem
    st = Image.new("RGBA", (n, n), (0, 0, 0, 0))
    for i in range(n * 2 // 16, n - n // 8):
        for w in range(max(1, n // 16)):
            st.putpixel((i, min(n - 1, n - 1 - i + w)), R["wood"][1 if w == 0 else 0])
    out["item/stick"] = st
    return out


def make_icon(out_dir, size=128):
    """pack.png: a 2x2 collage of grass, stone, planks and the gem (shown in the game's pack list)."""
    out_dir = Path(out_dir)
    icon = Image.new("RGBA", (size, size), (0, 0, 0, 255)); h = size // 2
    for i, name in enumerate(("block/grass_block_top", "block/stone", "block/oak_planks", "block/diamond_block")):
        t = Image.open(out_dir / f"{name}.png").convert("RGBA").resize((h, h), Image.NEAREST)
        icon.alpha_composite(t, ((i % 2) * h, (i // 2) * h))
    return icon


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("out"); ap.add_argument("--res", type=int, default=16, choices=[16, 32, 64]); ap.add_argument("--seed", type=int, default=5)
    ap.add_argument("--icon", help="also write the pack icon (pack.png) to this path; keep it OUTSIDE the textures folder")
    a = ap.parse_args(argv)
    out = Path(a.out)
    for key, val in make_all(a.res, a.seed).items():
        f = out / f"{key}.png"; f.parent.mkdir(parents=True, exist_ok=True)
        if isinstance(val, tuple):
            val[0].save(f); (out / f"{key}.png.mcmeta").write_text(json.dumps(val[1], indent=2))
        else:
            val.save(f)
    if a.icon:
        make_icon(out).save(a.icon)
    print(f"wrote {len(make_all(a.res, a.seed))} textures at {a.res}x to {out}" + (f" and the icon {a.icon}" if a.icon else ""))


if __name__ == "__main__":
    main()
